async initiateWithdrawal(userId: string, dto: InitiateWithdrawalDto) {
  const queryRunner = this.dataSource.createQueryRunner();
  await queryRunner.connect();
  await queryRunner.startTransaction();

  try {
    // 1. Récupérer le wallet de l'utilisateur avec verrouillage
    const wallet = await queryRunner.manager.findOne(Wallet, {
      where: { userId },
      lock: { mode: 'pessimistic_write' }
    });

    if (!wallet || wallet.balance < dto.amount) {
      throw new BadRequestException('Solde insuffisant.');
    }

    // 2. Bloquer les fonds (les déduire du solde disponible)
    wallet.balance -= dto.amount;
    wallet.blockedBalance += dto.amount;
    await queryRunner.manager.save(wallet);

    // 3. Créer la demande de retrait
    const withdrawal = queryRunner.manager.create(Withdrawal, {
      userId,
      amount: dto.amount,
      phoneNumber: dto.phoneNumber,
      operator: dto.operator,
      status: 'PENDING'
    });
    await queryRunner.manager.save(withdrawal);

    await queryRunner.commitTransaction();
    return withdrawal;
  } catch (error) {
    await queryRunner.rollbackTransaction();
    throw error;
  } finally {
    await queryRunner.release();
  }
}
